document.addEventListener('DOMContentLoaded',function(){var bar=document.querySelector('.sx-abas ul');if(!bar)return;var links=[].slice.call(bar.querySelectorAll('a[href^="#"]'));var secs=links.map(function(a){return document.querySelector(a.getAttribute('href'))});var cur=-1;function set(i){if(i===cur)return;cur=i;links.forEach(function(a,k){a.classList.toggle('on',k===i)});var a=links[i];if(a){bar.scrollLeft=a.offsetLeft-bar.clientWidth/2+a.offsetWidth/2}}function spy(){var y=(bar.parentElement.parentElement.getBoundingClientRect().bottom||60)+40,idx=0;secs.forEach(function(s,k){if(s&&s.getBoundingClientRect().top<=y)idx=k});set(idx)}addEventListener('scroll',spy,{passive:true});spy()});